import type { Db } from '@livingcv/db';
import { encrypt, decrypt, generateEncryptionKey, maskSecret } from '@livingcv/crypto';
import { ENCRYPTED_SETTING_KEYS, SETTING_KEYS } from '@livingcv/shared';

// The encryption key: the PORTFOLIO_ENCRYPTION_KEY env var is primary (the
// secure, recommended path). If it's absent, a bootstrap key generated by the
// setup wizard is stored (unencrypted, as the key itself) in app_settings so a
// brand-new self-host can encrypt secrets without a restart. The env var
// always takes precedence; security-conscious admins set it before first boot.
const BOOTSTRAP_KEY = 'bootstrap.encryption_key';

export function getEncryptionKey(db: Db): string {
  const fromEnv = process.env.PORTFOLIO_ENCRYPTION_KEY;
  if (fromEnv && fromEnv.trim()) return fromEnv.trim();
  const row = db
    .prepare<[string], { value: string }>('SELECT value FROM app_settings WHERE key = ?')
    .get(BOOTSTRAP_KEY);
  if (row && row.value) return row.value;
  throw new Error(
    'No encryption key available. Set PORTFOLIO_ENCRYPTION_KEY or run the setup wizard.',
  );
}

export function hasEncryptionKey(db: Db): boolean {
  const fromEnv = process.env.PORTFOLIO_ENCRYPTION_KEY;
  if (fromEnv && fromEnv.trim()) return true;
  const row = db.prepare<[string], { c: number }>('SELECT 1 AS c FROM app_settings WHERE key = ?').get(BOOTSTRAP_KEY);
  return row !== undefined;
}

// Generate + persist a bootstrap encryption key if none exists. Returns the
// key (so the wizard can display it for backup). No-op if the env var is set.
export function ensureEncryptionKey(db: Db): string {
  const fromEnv = process.env.PORTFOLIO_ENCRYPTION_KEY;
  if (fromEnv && fromEnv.trim()) return fromEnv.trim();
  const existing = db
    .prepare<[string], { value: string }>('SELECT value FROM app_settings WHERE key = ?')
    .get(BOOTSTRAP_KEY);
  if (existing && existing.value) return existing.value;
  const key = generateEncryptionKey();
  const now = new Date().toISOString();
  db.prepare(
    'INSERT OR REPLACE INTO app_settings (key, value, encrypted, updated_at) VALUES (?, ?, 0, ?)',
  ).run(BOOTSTRAP_KEY, key, now);
  return key;
}

// Read a setting as plaintext (decrypting encrypted rows). Server-side only.
export function getSetting(db: Db, key: string): string | null {
  const row = db
    .prepare<[string], { value: string; encrypted: number }>(
      'SELECT value, encrypted FROM app_settings WHERE key = ?',
    )
    .get(key);
  if (!row) return null;
  if (row.encrypted === 1) {
    return decrypt(row.value, getEncryptionKey(db));
  }
  return row.value;
}

// Write a setting, auto-encrypting rows whose key is in ENCRYPTED_SETTING_KEYS.
export function setSetting(db: Db, key: string, value: string): void {
  const now = new Date().toISOString();
  const encrypted = ENCRYPTED_SETTING_KEYS.has(key) ? 1 : 0;
  const stored = encrypted === 1 ? encrypt(value, getEncryptionKey(db)) : value;
  db.prepare(
    'INSERT OR REPLACE INTO app_settings (key, value, encrypted, updated_at) VALUES (?, ?, ?, ?)',
  ).run(key, stored, encrypted, now);
}

export function deleteSetting(db: Db, key: string): void {
  db.prepare('DELETE FROM app_settings WHERE key = ?').run(key);
}

// All settings as plaintext (decrypted). Server-side only.
export function getAllSettings(db: Db): Record<string, string> {
  const rows = db
    .prepare<[], { key: string; value: string; encrypted: number }>(
      'SELECT key, value, encrypted FROM app_settings',
    )
    .all();
  const out: Record<string, string> = {};
  for (const r of rows) {
    out[r.key] = r.encrypted === 1 ? decrypt(r.value, getEncryptionKey(db)) : r.value;
  }
  return out;
}

// Browser-safe view: encrypted keys come back masked (••••last4), never as
// plaintext or ciphertext (§2 invariant 7).
export function getSettingForBrowser(db: Db, key: string): string {
  const row = db
    .prepare<[string], { value: string; encrypted: number }>(
      'SELECT value, encrypted FROM app_settings WHERE key = ?',
    )
    .get(key);
  if (!row) return '';
  if (row.encrypted === 1) {
    try {
      return maskSecret(decrypt(row.value, getEncryptionKey(db)));
    } catch {
      // Key changed / undecryptable: reveal presence only.
      return row.value ? '••••' : '';
    }
  }
  return row.value;
}

export function isSetupComplete(db: Db): boolean {
  const row = db
    .prepare<[string], { value: string }>('SELECT value FROM app_settings WHERE key = ?')
    .get(SETTING_KEYS.setupComplete);
  return row?.value === '1';
}

export function markSetupComplete(db: Db): void {
  setSetting(db, SETTING_KEYS.setupComplete, '1');
}
